function handleStorageAdmission(s,error,text,operationId,preserveDraft=false){if(error?.message!=='browser_storage_not_saved')return false;if(!preserveDraft&&session()===s&&!draft)draft=text;if(s.lastMessageDispatch?.operationId===operationId&&s.lastMessageDispatch.state==='submitting'&&!s.lastMessageDispatch.runId)s.lastMessageDispatch.state='not_dispatched';if(s.liveRun?.operationId===operationId&&s.liveRun.status==='running'&&!s.liveRun.runId){s.liveRun.status='not_dispatched';s.liveRun.error='browser_storage_not_saved';}s.messages.push({role:'status',text:'Browser saving failed before this request was sent. Your text is kept; retry saving explicitly before sending again.'});return true;}
async function retryWorkspaceSave(){if(workspaceDurability.status().head){syncCurrentWorkspaceComposer();try{await workspaceDurability.retry(state,{writer:workspaceWriter.status()==='writer'});document.querySelector('#storage-conflict')?.remove();toast('Current workspace saved locally. Nothing was sent or resumed.');return true;}catch{showPersistenceConflict('unavailable');return false;}}if(workspaceWriter.status()!=='writer'){showPersistenceConflict(workspaceWriter.status());return false;}const result=persistLegacyWorkspace({retry:true});if(result==='saved'){document.querySelector('#storage-conflict')?.remove();toast('Current workspace saved. Nothing was sent or resumed.',{kind:'success'});return true;}showPersistenceConflict(result==='conflict'?'conflict':'unavailable');return false;}

function toast(text,{kind='critical'}={}){const transient=kind==='success'||kind==='info',previous=document.querySelector('.toast');if(transient&&previous?.dataset?.toastKind==='critical')return;previous?._disposeToast?.();previous?.remove();const d=document.createElement('div');d.className='toast';d.dataset.toastKind=transient?kind:'critical';d.textContent=text;d.setAttribute('role','status');d.setAttribute('aria-live','polite');const close=document.createElement('button');close.type='button';close.textContent='×';close.setAttribute('aria-label','Dismiss notification');let timer=null,remaining=4000,started=0,hovered=false,focused=false;const clear=()=>{if(timer!==null){clearTimeout(timer);timer=null;remaining=Math.max(0,remaining-(Date.now()-started));}},remove=()=>{d._disposeToast?.();d.remove();},schedule=()=>{if(!transient||hovered||focused||timer!==null)return;started=Date.now();timer=setTimeout(remove,remaining);};const position=()=>{const r=(document.querySelector('.canvas-wrap')||document.querySelector('.main'))?.getBoundingClientRect();if(!r)return;d.style.setProperty('--toast-x',(r.left+r.width/2)+'px');d.style.setProperty('--toast-y',(r.top+(r.height>180?76:12))+'px');d.style.setProperty('--toast-width',Math.max(180,Math.min(480,r.width-32))+'px');};d._positionToast=position;d._disposeToast=()=>{clear();window.removeEventListener('resize',position);};d.addEventListener('pointerenter',()=>{hovered=true;clear();});d.addEventListener('pointerleave',()=>{hovered=false;schedule();});d.addEventListener('focusin',()=>{focused=true;clear();});d.addEventListener('focusout',e=>{if(d.contains(e.relatedTarget))return;focused=false;schedule();});close.addEventListener('click',remove);d.append(close);document.body.append(d);position();window.addEventListener('resize',position);schedule();}
function currentProject(){return state.projects.find(p=>p.id===state.projectId);}
function recordMessageDispatch(s,event,operationId){const pending=s.lastMessageDispatch;if(!pending||pending.operationId!==operationId)return;if(event.type==='run.started'&&pending.state==='submitting'&&!pending.runId&&event.sessionId===s.id&&event.mode==='live_model'){pending.runId=event.runId;pending.state='running';}if(pending.runId===event.runId&&['run.completed','run.failed','run.cancelled'].includes(event.type))pending.state=event.type.slice(4);}
