function budgetAvailable(goal=draft,planningContext=undefined,outputMode=null,strategyCalls=null){if(!apiState?.budget)return true;const b=apiState.budget,limits=apiState.limits||{},s=session(),context=planningContext===undefined?((planningReview?.approved&&planningReview?.sessionId===s.id&&planningReview.ids?.length)||(s.chatContextSelection||[]).some(x=>x.model===s.model)):planningContext,calls=Number.isInteger(strategyCalls)&&strategyCalls>0?strategyCalls:outputMode==='project'?(s.pendingPlan?.tasks?.length||MAX_WORKFLOW_TASKS)+1:outputMode==='goal-summary'||s.chatMode==='plan'&&s.pendingPlan&&!s.pendingPlan.clarificationQuestions?.length?1:s?.chatMode==='agent'?(s.pendingPlan?.tasks?.length||MAX_WORKFLOW_TASKS):requiresDesignDraft({mode:s?.chatMode||'plan',goal,planningContext:context,planContext:s.pendingPlan})?(limits.designPlanReservationCalls||2):1,required=Number.isFinite(limits.perCallReservationUsd)?limits.perCallReservationUsd*calls:limits.reservationUsd,available=Number.isFinite(b.availableUsd)?b.availableUsd:b.limitUsd-b.chargedUsd-b.reservedUsd;return !!b.enabled&&Number.isFinite(required)&&Math.floor(available*1e9)>=Math.ceil(required*1e9);}
