 if(editor.kind==='worker-continuation')return '<div class="editor-backdrop"><section class="name-editor" role="dialog" aria-modal="true" aria-label="Continuation option">'+(editor.preview?renderContinuationConfirmation(editor.preview,esc,{busy:editor.busy,error:editor.error}):'<h2>Review remaining work</h2><p>'+esc(editor.error||'Checking repaired prerequisites and remaining budget…')+'</p><button data-action="cancel-editor">Close</button>')+'</section></div>';
