 if(editor.kind==='restore'){return `<div class="editor-backdrop"><section class="name-editor checkpoint-restore-dialog" role="dialog" aria-modal="true" aria-label="Restore checkpoint"><h2>Restore generated files?</h2><p>${editor.preview.changed.length} file(s) will change in this session's Mulow-owned workspace. Current files are checkpointed first. Plan approval will be cleared. Costs, external actions and original history remain unchanged.</p><ul>${editor.preview.changed.map(p=>'<li>'+esc(p)+'</li>').join('')}</ul><div class="checkpoint-restore-actions"><button data-action="cancel-editor">Cancel</button><button data-action="confirm-restore">Restore files</button></div></section></div>`;}
 if(editor.kind==='artifact'){const a=session().artifacts?.find(a=>a.id===editor.id);if(a&&a.contentAvailable===false)return `<div class="editor-backdrop"><section class="artifact-editor" role="dialog" aria-modal="true" aria-label="File metadata"><header><h2>${esc(a.name)}</h2><button data-action="cancel-editor">Close</button></header><p>Structure reference only. The original file contents were not included in this import.</p></section></div>`;return a?`<div class="editor-backdrop"><section class="artifact-editor" role="dialog" aria-modal="true" aria-label="File contents"><header><h2>${esc(a.name)}</h2><button data-action="cancel-editor">Close</button></header><p>${editor.current?'Current generated workspace file':'Saved artifact version'} · execution not verified</p><button data-current-file="${esc(a.id)}">Open current workspace version</button><pre>${esc(editor.current?.content??a.content)}</pre><button data-artifact="${esc(a.id)}">Download</button></section></div>`:'';}
