function renderBuildApprovalControl(s){const documentDraft=documentDraftBlocksBuild(),contextual=!documentDraft&&!!s.pendingPlan&&!s.pendingPlan.remoteStudy&&!planBlocked(s)&&!goalTransitionBlocksRun(s)&&(!s.pendingPlan.needsDesignDraft||!!s.pendingPlan.architecture)&&!liveControllers.size&&!archived()&&liveEnabled()&&runtimeCurrent()&&!workspaceStorageConflict();let ready=false,reason='Review and approve this exact plan. This does not start generation.';if(s.pendingPlan){const review=createGenerationReview(s,inputRevision(s),apiState);ready=!!review.assessment;if(!ready)reason=review.error;}if(documentDraft)reason='Save or cancel the document edit, and finish current document work before Build review.';else if(s.pendingPlan?.stale&&s.planDocumentRevision&&(!s.pendingPlan.documentBinding||s.pendingPlan.documentBinding.revisionId!==s.planDocumentRevision.revisionId||s.pendingPlan.documentBinding.documentDigest!==s.planDocumentRevision.documentDigest))reason='The Plan document changed. Generate a new design before Build review.';else if(s.pendingPlan?.stale)reason='The plan or its inputs changed. Review the current Plan before Build approval.';const label=currentPlanHasBuildAttempt(s)?'Review plan':contextual&&!ready?'Build unavailable':currentBuildApproval(s)?'Approved':'Approve plan';return '<button type="button" class="goal-approve" data-action="generate-project" '+(contextual?'':'disabled')+' title="'+esc(reason)+'" aria-label="'+esc(label+'. '+reason)+'">'+label+'</button>';}

