 const recovery=r.recovery,branch=recovery?.eligible===true,separate=branch&&recovery.separatePlanExpanded===true,closed=recovery?.blocker==='closed_not_dispatched',kind=r.review?.restoreKind,linked=kind==='linked',planOnly=kind==='plan_only',exactConversation=kind==='conversation_only'&&!!r.review?.checkpointId&&!!r.review.target?.planRunId&&r.review.target.planRunId===r.review.current?.planRunId&&r.review.target.sourceRevision===r.review.current?.sourceRevision,ready=!recovery&&r.review?.readiness==='ready'&&!r.busy&&!r.error;
