async function openExecutionDiagnostics(){const target=session();setEditor({kind:'execution',sessionId:target.id,record:target.executionChecks?.at(-1)||null,busy:executionControllers.has(target.id)&&target.executionChecks?.at(-1)?.status==='running'});const current=editor;render();try{const response=await fetch('/api/execution/capabilities',{cache:'no-store'});if(!response.ok)throw Error('Execution diagnostics are unavailable. Restart the updated local server.');const capabilities=await response.json();if(editor!==current||session().id!==target.id)return;current.capabilities=capabilities;if(current.record?.runId&&!current.busy){const historyResponse=await fetch('/api/runs/'+encodeURIComponent(current.record.runId),{cache:'no-store'});if(historyResponse.ok){const history=await historyResponse.json();if(history.sessionId!==target.id||history.id!==current.record.runId)throw Error('Execution history binding mismatch');const recovered={sessionId:target.id,status:'unverified',events:[],fixtureOnly:true};for(const event of history.events||[])applyExecutionEvent(recovered,event);if(editor===current&&session().id===target.id){current.record=recovered;const index=target.executionChecks.findIndex(r=>r.runId===recovered.runId);if(index>=0)target.executionChecks[index]=recovered;save();}}}}catch(e){if(editor===current)current.error=e.message;}if(editor===current)render();}
async function approveExecutionFixture(form){const current=editor,target=session();if(current?.kind!=='execution'||current.sessionId!==target.id||current.busy)return;if(!liveEnabled()||!runtimeCurrent()||archived()){toast('Connect the current local runtime before approving a developer fixture.');return;}try{const input=approvalRequest(target.id,current.capabilities,Number(form.querySelector('[name=attempts]').value));current.busy=true;render();const response=await fetch('/api/execution/approve',{method:'POST',headers:{'Content-Type':'application/json','X-MusePilot-CSRF':apiState.csrf},body:JSON.stringify(input)});const result=await response.json();if(!response.ok)throw Error(result.error||'Approval failed');if(result.sessionId!==target.id||result.snapshotHash!==input.snapshotHash||result.maxAttempts!==input.maxAttempts)throw Error('Approval context mismatch');if(editor===current&&session().id===target.id)current.approval=result;}catch(e){current.error=e.message;}finally{current.busy=false;if(editor===current)render();}}
async function runExecutionFixture(){const current=editor,target=session();if(current?.kind!=='execution'||current.sessionId!==target.id||!current.approval||current.busy)return;if(!liveEnabled()||!runtimeCurrent()||archived()||liveControllers.size){toast('Wait for active work and connect the current runtime first.');return;}const approval=current.approval;current.approval=null;current.busy=true;current.error='';const record={sessionId:target.id,status:'running',events:[],fixtureOnly:true};current.record=record;target.executionChecks||=[];target.executionChecks.push(record);const controller=new AbortController();liveControllers.set(target.id,controller);executionControllers.set(target.id,controller);save();render();try{const response=await fetch('/api/execution/run',{method:'POST',headers:{'Content-Type':'application/json','X-MusePilot-CSRF':apiState.csrf},body:JSON.stringify({sessionId:target.id,operationId:'fixture_'+crypto.randomUUID(),approvalId:approval.approvalId}),signal:controller.signal});await consumeNDJSON(response,event=>{applyExecutionEvent(record,event);save();if(editor?.kind==='execution'&&editor.sessionId===target.id&&editor.record===record&&session().id===target.id)render();});if(record.status==='running')throw Error('No terminal verification result received');}catch(e){record.status='unverified';current.error='Verification not confirmed: '+e.message;if(editor?.kind==='execution'&&editor.record===record)editor.error=current.error;}finally{current.busy=false;executionControllers.delete(target.id);liveControllers.delete(target.id);save();if(editor?.kind==='execution'&&editor.sessionId===target.id&&editor.record===record&&session().id===target.id){editor.busy=false;render();}await refreshLiveStatus().catch(()=>{});}}

async function requestSteer(id,commandText=null){const target=session(),pendingKey=target.id+':'+target.liveRun?.runId;let ownsPending=false;try{if(!runtimeCurrent()||!liveEnabled())throw Error('Connect the current runtime to steer active work. Offline plans are not executing.');const request=steeringRequest(target,id);if(pendingSteeringRequests.has(pendingKey))throw Error('Wait for the current steering request.');pendingSteeringRequests.add(pendingKey);ownsPending=true;const response=await fetch('/api/steer',{method:'POST',headers:{'Content-Type':'application/json','X-MusePilot-CSRF':apiState.csrf},body:JSON.stringify(request)});const result=await response.json();if(!response.ok)throw Error(result.error||'Steering request was rejected');if(result.accepted!==true||result.targetTaskId!==request.targetTaskId)throw Error('Steering acknowledgement mismatch');if(target.liveRun?.runId!==request.runId)return;if(commandText){const message={role:'user',text:commandText};recordConversationActivity(target,message);target.messages.push(message);}if(session().id===target.id){if(commandText&&draft.trim()===commandText)draft='';toast(packageSteeringMode(target)?'Priority accepted. Current package, repair and checkpoint settle first.':'Steering accepted. Active work finishes before the queued priority changes.',{kind:'info'});}save();render();}catch(e){if(session().id===target.id)toast(e.message);}finally{if(ownsPending)pendingSteeringRequests.delete(pendingKey);}}




