// Stale tabs retain their in-memory work, but cannot initiate new mutations.
// Copy/export and stopping existing work remain available; no automatic reload.
function staleTabAllowsControl(target){const control=target?.closest?.('button,[data-edit-message],[data-plan-branch],[data-static-entry],[data-external-restore]');if(!control)return true;const d=control.dataset||{};if(d.action==='pause-work')return !!ownedCancelableRun(session());if(d.action==='check-run-control')return true;if(d.menuCommand==='export-structure'||d.menuCommand==='project-context')return true;if(['planFocusComponent','planFocusTask','menuSession','menuProject','copyMessage','filesSelect','artifact','attachmentFile','downloadSource','sourceFile','currentFile'].some(key=>d[key]!==undefined))return true;return ['package-continuation-close','package-continuation-check','workspace-backup','workspace-backup-close','workspace-backup-download','workspace-backup-verify-file','migrate-workspace-storage','project-structure','goal-details','session-files','close-session-files','refresh-project-files','export-structure','export-project-structure','runtime-download-qa','runtime-stop','react-persistent-stop','react-persistent-back','react-persistent-check','react-persistent-download','persistent-confirm-cancel','trusted-crud-stop','trusted-crud-back','react-v2-stop','reviewed-react-stop','reviewed-artifact-stop','remote-study-stop','remote-study-close','static-source-stop','close-work','close-agent','architecture-close-details','close-planning-inputs','cancel-live','stop-execution-fixture','cancel-editor'].includes(d.action);}
app.addEventListener('click',event=>{if(workspaceStorageConflict()&&!staleTabAllowsControl(event.target)){event.preventDefault();event.stopImmediatePropagation();}},true);
app.addEventListener('submit',event=>{if(workspaceStorageConflict()){event.preventDefault();event.stopImmediatePropagation();}},true);
app.addEventListener('change',event=>{if(event.target.matches?.('[data-workspace-backup-file]'))return;if(workspaceStorageConflict()){event.preventDefault();event.stopImmediatePropagation();}},true);

app.addEventListener('drop',event=>{if(Array.from(event.dataTransfer?.types||[]).includes('Files')&&workspaceStorageConflict()){event.preventDefault();event.stopImmediatePropagation();}},true);

app.addEventListener('keydown',e=>{if(e.target.matches?.('p[data-edit-message]')&&['Enter',' '].includes(e.key)&&!e.isComposing){if(workspaceStorageConflict())return;e.preventDefault();openMessageEdit(Number(e.target.dataset.editMessage));}});

app.addEventListener('error',event=>{const image=event.target,selected=filesSelection;if(!image?.matches?.('img[data-files-image-id]')||!filesPanel||selected?.sessionId!==session().id||selected.id!==image.dataset.filesImageId||image.getAttribute('src')!==selected.imageURL)return;releaseFilesImage();selected.error='Image preview unavailable. Open the file to download its original.';render();},true);

app.addEventListener('change',e=>{if(e.target.matches?.('[data-message-recovery-consent]')&&editor?.kind==='message-edit'&&editor.resend?.recovery){editor.resend.recovery.consent=e.target.checked===true;render();}});

app.addEventListener('change',e=>{if(e.target.matches?.('[data-message-checkpoint-consent]')&&editor?.kind==='message-edit'&&editor.resend?.checkpointRecovery&&!editor.resend.busy){editor.resend.checkpointRecovery.consent=e.target.checked===true;render();document.querySelector('[data-message-checkpoint-consent]')?.focus();}});

function updateClarificationInput(field){const context=currentClarificationChoices(),selection=clarificationSelection;if(!context||!selection||field.dataset.clarificationToken!==selection.token||selection.key!==context.key||selection.busy||field.disabled)return;try{selection.text=field.value;selectClarificationOption(context,selection,'custom');const card=field.closest('.clarification-choices');card?.querySelectorAll('[data-clarification-choice]').forEach(b=>b.setAttribute('aria-pressed','false'));const send=card?.querySelector('[data-clarification-send]');if(send)send.disabled=!selection.text.trim()||selection.text.trim().length>600;}catch{}}
app.addEventListener('keydown',e=>{const card=e.target.closest?.('.clarification-choices');if(!card||e.isComposing)return;const input=e.target.matches('[data-clarification-input]'),choice=e.target.closest?.('[data-clarification-choice]');if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();card.querySelector('[data-clarification-dismiss]')?.click();}else if(e.key==='Enter'&&(input||choice&&clarificationSelection?.selectedId===choice.dataset.clarificationChoice)){e.preventDefault();e.stopImmediatePropagation();card.querySelector('[data-clarification-send]')?.click();}else if(['1','2'].includes(e.key)&&!e.target.matches('input,textarea,[contenteditable="true"]')){e.preventDefault();e.stopImmediatePropagation();card.querySelector('[data-clarification-choice="'+e.key+'"]')?.click();}},true);

app.addEventListener('compositionstart',e=>{if(e.target.matches('[data-clarification-input]')&&clarificationSelection&&e.target.dataset.clarificationToken===clarificationSelection.token)clarificationSelection.composing=true;});
app.addEventListener('compositionend',e=>{if(!e.target.matches('[data-clarification-input]')||!clarificationSelection||e.target.dataset.clarificationToken!==clarificationSelection.token)return;updateClarificationInput(e.target);clarificationSelection.composing=false;render();});

app.addEventListener('cancel',e=>{if(e.target.id==='external-source-file')returnToSourceFiles();},true);

app.addEventListener('keydown',e=>{const edge=e.target.closest?.('[data-architecture-edge]');if(edge&&['Enter',' '].includes(e.key)){e.preventDefault();edge.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});

if(typeof window!=='undefined')window.addEventListener('beforeunload',event=>{if((typeof planDocuments!=='undefined'&&planDocuments.hasUnsavedDrafts())||persistenceDiagnostic(state)||['saving','conflict','unavailable'].includes(workspaceDurability.status().mode)){event.preventDefault();event.returnValue='';}});

app.addEventListener('change',event=>{if(event.target.matches?.('[data-workspace-backup-file]')){const file=event.target.files?.[0];event.target.value='';void verifySelectedWorkspaceBackup(file);}},true);

app.addEventListener('input',event=>{if(workspaceWriter.status()!=='writer'||!event.target.matches?.('#composer textarea,[data-clarification-input],#message-edit-form textarea'))return;const buffers=workspaceDraftSnapshot();state.workspaceDraftBuffers={...(state.workspaceDraftBuffers||{}),[buffers.sessionId]:buffers};save();});

app.addEventListener('input',e=>{if(e.target.matches?.('[data-document-editor]')&&e.target.closest('[data-document-view-key]')?.getAttribute('data-document-view-key')===planDocumentViewKey(planDocuments.state()))planDocuments.editText(e.target.value);});
app.addEventListener('change',e=>{if(e.target.matches?.('[data-document-file]')){const file=e.target.files?.[0];e.target.value='';if(file)void planDocumentImport.choose(file);else planDocumentImport.cancel();}});
app.addEventListener('keydown',e=>{if(e.key==='Escape'&&e.target.closest?.('.plan-document-generation-review')&&!planDocuments.state().busy){e.preventDefault();planDocuments.cancelReview();document.querySelector('[data-document-action=review-design]')?.focus();}});

app.addEventListener('cancel',e=>{if(e.target.matches?.('[data-document-file]')){planDocumentImport.cancel();render();document.querySelector('[data-document-action=import]')?.focus();}});

app.addEventListener('change',e=>{if(e.target.matches?.('[data-local-plan-files],[data-local-plan-folder]')){const files=Array.from(e.target.files||[]);e.target.value='';if(files.length)void stagePlanCodebase(files);}else if(e.target.matches?.('[data-local-plan-consent]'))localPlanSource.select(e.target.checked===true);});
app.addEventListener('cancel',e=>{if(e.target.matches?.('[data-local-plan-files],[data-local-plan-folder]')){render();document.querySelector('[data-document-action=codebase],[data-action=choose-local-plan]')?.focus();}});

app.addEventListener('input',e=>{if(!e.target.matches?.('[data-document-custom]'))return;const v=planDocuments.state(),key=e.target.closest('[data-document-question-key]')?.dataset.documentQuestionKey,i=Number(e.target.dataset.documentCustom);if(key!==documentQuestionKey(v)||v.sessionId!==session().id||v.busy||v.editing)return;const s=session();s.documentReplies||={};s.documentReplies[key]={...(s.documentReplies[key]||{}),[i]:{kind:'custom',text:e.target.value.slice(0,2000)}};const row=e.target.closest('[data-question-index]');for(const button of row.querySelectorAll('[data-document-choice]'))button.setAttribute('aria-pressed','false');const next=e.target.closest('[data-document-question-key]').querySelector('[data-document-continue]');if(next)next.disabled=!documentReplyText(v,key,s.documentReplies[key]);save();});

app.addEventListener('input',e=>{if(e.target.matches?.('#agent-change-form textarea')&&editor?.kind==='agent-change'){editor.text=e.target.value;}});
